142	bool is_valid_utf8(const std::string& s) {
143	    const auto* p = reinterpret_cast<const unsigned char*>(s.data());
144	    size_t i = 0;
145	    while (i < s.size()) {
146	        unsigned c = p[i];
147	        size_t extra = 0;
148	        unsigned codepoint = 0;
149	        if (c < 0x80) {
150	            ++i;
151	            continue;
152	        }
153	        if ((c & 0xe0) == 0xc0) {
154	            extra = 1;
155	            codepoint = c & 0x1f;
156	        } else if ((c & 0xf0) == 0xe0) {
157	            extra = 2;
158	            codepoint = c & 0x0f;
159	        } else if ((c & 0xf8) == 0xf0) {
160	            extra = 3;
161	            codepoint = c & 0x07;
162	        } else {
163	            return false;
164	        }
165	        if (i + extra >= s.size()) return false;
166	        for (size_t j = 1; j <= extra; ++j) {
167	            if ((p[i + j] & 0xc0) != 0x80) return false;
168	            codepoint = (codepoint << 6) | (p[i + j] & 0x3f);
169	        }
170	        if (codepoint < (extra == 1 ? 0x80u : extra == 2 ? 0x800u : 0x10000u)) {
171	            return false;  // overlong encoding
172	        }
173	        if (codepoint >= 0xd800 && codepoint <= 0xdfff) return false;  // surrogate
174	        if (codepoint > 0x10ffff) return false;
175	        i += extra + 1;
