195	std::string escape_dn_value(const std::string& value) {
196	    std::string out;
197	    for (size_t i = 0; i < value.size(); ++i) {
198	        unsigned char c = static_cast<unsigned char>(value[i]);
199	        if (c == ',' || c == '+' || c == '=' || c == '"' || c == '\\' ||
200	            c == '<' || c == '>' || c == '#' || c == ';') {
201	            out.push_back('\\');
202	            out.push_back(static_cast<char>(c));
203	        } else if (c == ' ' && (i == 0 || i + 1 == value.size())) {
204	            out.append("\\ ");
205	        } else if (c < 0x20) {
206	            char buf[5];
207	            std::snprintf(buf, sizeof(buf), "\\%02X", c);
208	            out.append(buf);
209	        } else {
210	            out.push_back(static_cast<char>(c));
211	        }
212	    }
213	    return out;
