268	bool format_time(const ASN1_TIME* time, std::string& out) {
269	    struct tm tm_value {};
270	    if (ASN1_TIME_to_tm(time, &tm_value) != 1) return false;
271	    char buffer[32];
272	    int written = std::snprintf(
273	        buffer, sizeof(buffer), "%04d-%02d-%02dT%02d:%02d:%02dZ",
274	        tm_value.tm_year + 1900, tm_value.tm_mon + 1, tm_value.tm_mday,
275	        tm_value.tm_hour, tm_value.tm_min, tm_value.tm_sec);
276	    if (written <= 0 || static_cast<size_t>(written) >= sizeof(buffer)) {
277	        return false;
278	    }
279	    out.assign(buffer);
280	    return true;
