421	int main(int argc, char* argv[]) {
422	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
423	        std::cout << "trustpeek 0.1.0\n";
424	        return 0;
425	    }
426	    if (argc == 3 && std::string_view(argv[1]) == "inspect") {
427	        return inspect_file(argv[2]);
428	    }
429	    print_usage();
430	    return 2;
